  "@context": "https://schema.org",
  "@type": "FAQPage",
  "mainEntity": [
    {
      "@type": "Question",
      "name": "هل يختلف تجهيز المكتب الميداني عن تجهيز المقر الرئيسي؟",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "نعم، رغم أنه امتداد تشغيلي للمقر. المكتب الميداني يعمل في بيئة مغبرة رطبة عالية الاستهلاك، فيحتاج أجهزة مصممة للاستخدام المكثف، وورقًا يتحمّل ظروف الحفظ الميداني، ومخزنًا منظمًا داخل الكرفان."
      }
    },

    {
      "@type": "Question",
      "name": "ما الفرق بين الشراء الفردي والعقد السنوي في توريد المستلزمات؟",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "الشراء الفردي يعني طلب كل احتياج على حدة، وهو مرن ظاهريًا لكنه يرفع سعر الوحدة ويضيف كلفة توصيل متكررة. العقد السنوي يحدد المواصفات والكميات والجدولة مسبقًا، فتحصل على شروط أفضل وأولوية في التسليم واستقرار في نوع الورق والحبر بين الشحنات."
      }
    },

    {
      "@type": "Question",
      "name": "هل أحتاج ماكينة تصوير في الموقع أم تكفي طابعة عادية؟",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "يعتمد على حجم الطباعة اليومي في الموقع. المشروع الذي يُصدر عشرات النسخ يوميًا من تقارير وسجلات يحتاج ماكينة تصوير مصممة للاستخدام المكثف."
      }
    },

    {
      "@type": "Question",
      "name": "كيف أحدد الكمية المناسبة من ورق الطباعة لكل مرحلة؟",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "اربط الكمية بنوع المرحلة وحجم فريقها. مرحلة الأساسات تنتج تقارير حفر وصب يومية، ومرحلة التشطيبات تنتج أوامر تغيير ومحاضر استلام مكثفة."
      }
    },

    {
      "@type": "Question",
      "name": "كيف أحمي مستلزمات الطباعة من أضرار بيئة الموقع؟",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "خصص خزانة معدنية داخل الكرفان الإداري بعيدًا عن الأرضية والنوافذ، وحافظ على تهوية معقولة لتخفيف الرطوبة، وأبقِ الورق داخل غلافه الأصلي حتى وقت الاستخدام."
      }
    },

    {
      "@type": "Question",
      "name": "ما أبرز المستلزمات التي تُغفلها الشركات عند تجهيز موقع جديد؟",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "دولاب الأرشفة القابل للإغلاق، الأختام الرسمية للفرع الميداني، مظاريف بمقاسات موحدة لإرسال الملفات إلى المقر، رزم ورق احتياطية بجرامية موحدة مع المقر، وأقلام توقيع مقاومة للحرارة."
      }
    }
  ]
}
